/** Keys stored in `career_interviews.evaluation` (JSON) — must match backend validation */
export const INTERVIEW_EVALUATION_CRITERIA = [
    { key: 'technical_skills', label: 'المهارات التقنية' },
    { key: 'soft_skills', label: 'المهارات الشخصية' },
    { key: 'question_answers', label: 'إجابة الأسئلة' },
    { key: 'manager_impression', label: 'انطباع المدير' },
    { key: 'practical_result', label: 'النتيجة العملية' },
] as const;

export type InterviewEvaluationKey = (typeof INTERVIEW_EVALUATION_CRITERIA)[number]['key'];

export function averageEvaluationPercent(
    evaluation: Partial<Record<InterviewEvaluationKey, number>> | null | undefined,
): number {
    const vals = INTERVIEW_EVALUATION_CRITERIA.map(({ key }) => {
        const v = evaluation?.[key];
        return typeof v === 'number' && !Number.isNaN(v) ? v : 0;
    });
    if (vals.length === 0) return 0;
    return Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
}
